      Effect.timeoutOption(3000),
      Effect.map((exit) => {
        const failed = startError();

        return failed !== null
          ? new ConnectFailure({
              kind: "needs-attention",
              reason: missingReason,
              detail: `${command}: ${failed.code ?? failed.message}`,
