  hour: "2026-10-11T09:00:00.000Z",
  harness: "claude",
  model: "claude-opus-5",
  sessionId: null,
  tokens: {
    input: 230_000,
    cacheRead: 3_300_000,
    cacheWrite: 96_000,
    output: 174_000,
    reasoning: 0,
    cacheWrite1h: 0,
  },
  reportedCost: null,
  longContext: [],
